{"implementation": "def solve(case):
    payload = case["payload"]
    segments = payload["segments"]
    budget = payload["budget"]

    # Validate required fields
    for seg in segments:
        for field in ["name", "importance", "minimum", "capacity"]:
            if field not in seg:
                raise ValueError(f"Missing required field '{field}' in segment")

    names = [seg["name"] for seg in segments]
    importance = [seg["importance"] for seg in segments]
    minimums = [seg["minimum"] for seg in segments]
    capacities = [seg["capacity"] for seg in segments]

    quota_sum = sum(minimums)
    total_capacity = sum(capacities)

    if budget < quota_sum:
        raise ValueError(f"Budget {budget} is below minimum quota sum {quota_sum}")
    if budget > total_capacity:
        raise ValueError(f"Budget {budget} exceeds total capacity {total_capacity}")

    # Initialize every segment at its minimum quota
    allocations = list(minimums)
    remaining = budget - quota_sum

    # Greedy allocation: give one token at a time to segment with highest importance/(current+1)
    # Ties broken by original segment order (lower index wins)
    while remaining > 0:
        best_idx = -1
        best_priority = -1.0

        for i in range(len(segments)):
            if allocations[i] >= capacities[i]:
                continue
            priority = importance[i] / (allocations[i] + 1)
            # Strict greater-than preserves tie-break by original order
            if priority > best_priority:
                best_priority = priority
                best_idx = i

        if best_idx == -1:
            break  # All segments at capacity

        allocations[best_idx] += 1
        remaining -= 1

    name_mapping = {names[i]: allocations[i] for i in range(len(segments))}

    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "total": sum(allocations)
    }
"}
